    ssrfBlocked = true;
    ssrfBlockedReason = ssrfCheckEdit.reason;
  } else {
    sql = `UPDATE trading.rss_sources SET
      name = ${pgStr(name)}, url = ${pgStr(url)}, updated_at = now()
    WHERE id = ${id};`;
  }
} else if (action === 'delete' && id !== null) {
